"% Monte Carlo robustness screening - closed-loop short-period spec

clear; clc;

% Nominal longitudinal parameters
V = 740.0;
Xu = -0.006; Xw = 0.033;
Zu = -0.027; Zw = -0.66;
Mw = -0.0046; Mq = -0.78;
g = 32.174;

A_nom = [Xu,  Xw,  0,  -g;
         Zu,  Zw,  V,   0;
         0,   Mw,  Mq,  0;
         0,    0,  1,   0];

B = [0; -5.5; -4.5; 0];

% Open-loop eigenvalues
ol_poles = eig(A_nom);

% Identify phugoid poles (lowest natural frequency)
mags_ol = abs(ol_poles);
[~, idx_ol] = sort(mags_ol);
phugoid_poles = ol_poles(idx_ol(1:2));

% Desired short-period poles (omega_n = 2.1, zeta = 0.55)
omega_n_d = 2.1;
zeta_d = 0.55;
sp_desired = [-zeta_d*omega_n_d + 1j*omega_n_d*sqrt(1-zeta_d^2), ...
              -zeta_d*omega_n_d - 1j*omega_n_d*sqrt(1-zeta_d^2)];

% Pole placement: short-period at desired location, phugoid held at open-loop
desired_poles = [sp_desired, phugoid_poles];
K = place(A_nom, B, desired_poles);

% Monte Carlo sampling (deterministic via fixed seeds)
N = 200;
pct = 0.20;

rng(20260828);
f_Mw = 1 + pct*(2*rand(N,1) - 1);

rng(20261828);
f_Zw = 1 + pct*(2*rand(N,1) - 1);

rng(20262828);
f_Mq = 1 + pct*(2*rand(N,1) - 1);

% Evaluate closed-loop short-period at each sample
count = 0;
for i = 1:N
    A_i = A_nom;
    A_i(2,2) = f_Zw(i) * Zw;
    A_i(3,2) = f_Mw(i) * Mw;
    A_i(3,3) = f_Mq(i) * Mq;

    cl_poles_i = eig(A_i - B*K);

    % Identify short-period mode (highest natural frequency)
    mags_i = abs(cl_poles_i);
    [~, sp_idx] = max(mags_i);
    s_sp = cl_poles_i(sp_idx);

    omega_n_i = abs(s_sp);
    zeta_i = -real(s_sp) / omega_n_i;

    if (omega_n_i >= 2.0) && (omega_n_i <= 2.2) && (zeta_i >= 0.52)
        count = count + 1;
    end
end

pass_fraction = count / N;
failing_case_count = N - count;

% Write result.json
result.pass_fraction = pass_fraction;
result.failing_case_count = failing_case_count;

json_text = jsonencode(result);
fid = fopen('result.json', 'w');
fwrite(fid, json_text);
fclose(fid);"

